// Tests for PhoneLink.swift. Run with herdi-mac/test.sh.
import Foundation

var failures = 0

func check(_ name: String, _ ok: Bool, _ detail: @autoclosure () -> String = "") {
    if ok {
        print("  pass: \(name)")
    } else {
        failures += 1
        print("  FAIL: \(name) \(detail())")
    }
}

let token = "4f9c" + String(repeating: "0", count: 56) + "e21a"

func named(_ host: String) -> [String: String] {
    ["HERDR_TUNNEL_MODE": "named", "HERDR_TUNNEL_NAME": "herdr-relay", "HERDR_TUNNEL_HOSTNAME": host]
}

let installerConfig = """
# herdr-remote configuration (generated by install-service.sh)
HERDR_RELAY_PORT=8375
HERDR_SESSION=
HERDR_TUNNEL_MODE=named
HERDR_TUNNEL_HOSTNAME=relay.example.com
"""
let parsed = parseEnvFile(installerConfig)
check("reads a key the installer writes", parsed["HERDR_TUNNEL_HOSTNAME"] == "relay.example.com")
check("reads an empty value as empty", parsed["HERDR_SESSION"] == "")
check("skips the comment line", parsed.count == 4, "got \(parsed.count) keys")
check("drops quotes and an export prefix someone added by hand",
      parseEnvFile("export HERDR_TUNNEL_HOSTNAME=\"relay.example.com\"\nB='x'")
          == ["HERDR_TUNNEL_HOSTNAME": "relay.example.com", "B": "x"])
check("keeps an equals sign inside the value", parseEnvFile("A=b=c")["A"] == "b=c")

let ready = phoneLink(config: named("relay.example.com"), secrets: ["HERDR_RELAY_TOKEN": token])
check("gives a named tunnel with a token a link that holds the token",
      ready == .ready(link: "https://relay.example.com/?token=\(token)", address: "https://relay.example.com"),
      "got \(ready)")

check("accepts a hostname typed with a scheme and a trailing slash",
      phoneLink(config: named("https://relay.example.com/"), secrets: ["HERDR_RELAY_TOKEN": token])
          == .ready(link: "https://relay.example.com/?token=\(token)", address: "https://relay.example.com"))

check("warns about a named tunnel with no token",
      phoneLink(config: named("relay.example.com"), secrets: ["HERDR_RELAY_TOKEN": ""])
          == .noToken(address: "https://relay.example.com"))
check("warns about a named tunnel when secrets.env is missing",
      phoneLink(config: named("relay.example.com"), secrets: nil) == .noToken(address: "https://relay.example.com"))

let tunnelLog = """
2026-10-20T12:03:01Z INF Requesting new quick Tunnel on trycloudflare.com...
2026-10-20T12:03:02Z INF +--------------------------------------------------------------------------------------------+
2026-10-20T12:03:02Z INF |  Your quick Tunnel has been created! Visit it at (it may take some time to be reachable):  |
2026-10-20T12:03:02Z INF |  https://old-words-here.trycloudflare.com                                                  |
2026-10-20T14:10:00Z ERR Failed to fetch quick Tunnel error="Post \"https://api.trycloudflare.com/tunnel\": EOF"
2026-10-20T14:10:09Z INF |  https://fresh-river-name.trycloudflare.com                                                |
2026-10-20T14:10:09Z INF Registered tunnel connection connIndex=0
"""
let temp = ["HERDR_TUNNEL_MODE": "temp"]
check("takes the newest temp tunnel address from the log, not the api host",
      latestTempTunnelAddress(tunnelLog) == "https://fresh-river-name.trycloudflare.com",
      "got \(latestTempTunnelAddress(tunnelLog) ?? "nil")")
check("finds no address in a log that has none",
      latestTempTunnelAddress("2026-10-20T12:03:01Z INF Starting tunnel") == nil)
check("gives a temp tunnel a code, marked as one that changes",
      phoneLink(config: temp, secrets: ["HERDR_RELAY_TOKEN": token], tunnelLog: tunnelLog)
          == .temporary(link: "https://fresh-river-name.trycloudflare.com/?token=\(token)",
                        address: "https://fresh-river-name.trycloudflare.com"))
check("tells a temp tunnel with no address in the log that the tunnel is not running",
      phoneLink(config: temp, secrets: ["HERDR_RELAY_TOKEN": token], tunnelLog: "") == .tempTunnel)
check("tells a temp tunnel with no log that the tunnel is not running",
      phoneLink(config: temp, secrets: ["HERDR_RELAY_TOKEN": token], tunnelLog: nil) == .tempTunnel)
check("warns about a temp tunnel with no token",
      phoneLink(config: temp, secrets: nil, tunnelLog: tunnelLog)
          == .noToken(address: "https://fresh-river-name.trycloudflare.com"))
check("shows the setup steps when the installer never ran",
      phoneLink(config: nil, secrets: nil) == .noTunnel)
check("shows the setup steps when the tunnel is off",
      phoneLink(config: ["HERDR_TUNNEL_MODE": "none"], secrets: ["HERDR_RELAY_TOKEN": token]) == .noTunnel)
check("shows the setup steps for a named tunnel with no hostname",
      phoneLink(config: named(""), secrets: ["HERDR_RELAY_TOKEN": token]) == .noTunnel)

for bad in ["relay", "relay.example.com/path", "relay example.com", "user@relay.example.com", "-relay.example.com"] {
    check("refuses \"\(bad)\" as a hostname",
          phoneLink(config: named(bad), secrets: ["HERDR_RELAY_TOKEN": token]) == .noTunnel)
}

check("escapes a token that is not plain hex",
      phoneLink(config: named("relay.example.com"), secrets: ["HERDR_RELAY_TOKEN": "a&b=c d"])
          == .ready(link: "https://relay.example.com/?token=a%26b%3Dc%20d", address: "https://relay.example.com"))

for (name, expected) in [("named", PhoneLink.ready(link: "https://relay.example.com/?token=preview", address: "https://relay.example.com")),
                         ("temp", .temporary(link: "https://example-words-here.trycloudflare.com/?token=preview",
                                             address: "https://example-words-here.trycloudflare.com")),
                         ("temp-waiting", .tempTunnel), ("none", .noTunnel),
                         ("no-token", .noToken(address: "https://relay.example.com"))] {
    check("previews the \(name) window with a made-up address and no real token", previewPhoneLink(name) == expected)
}
check("ignores a preview name it does not know", previewPhoneLink("everything") == nil)

print(failures == 0 ? "PhoneLink: all passed" : "PhoneLink: \(failures) failed")
exit(failures == 0 ? 0 : 1)
